		'wpbp-content',
		array(
			'label'       => __( 'WPBP Content', 'wpbp' ),
			'description' => __( 'Abilities for working with content.', 'wpbp' ),
		)
	);

	wp_register_ability(
		'wpbp/count-words',
		array(
			'label'               => __( 'Count Words', 'wpbp' ),
			'description'         => __( 'Counts the number of words in the supplied text.', 'wpbp' ),
			'category'            => 'wpbp-content',
			'input_schema'        => array(
				'type'       => 'object',
				'properties' => array(
					'text' => array(
						'type'        => 'string',
						'description' => __( 'The text to count words in.', 'wpbp' ),
					),
				),
				'required'   => array( 'text' ),
			),
			'output_schema'       => array(
				'type'        => 'integer',
				'description' => __( 'The number of words in the text.', 'wpbp' ),
			),
			'execute_callback'    => static function ( $input ) {
				$text = isset( $input['text'] ) ? (string) $input['text'] : '';
				$text = trim( $text );

				if ( '' === $text ) {
					return 0;
				}

				$words = preg_split( '/\s+/u', $text, -1, PREG_SPLIT_NO_EMPTY );

				return is_array( $words ) ? count( $words ) : 0;
			},
			'permission_callback' => static function () {
				return current_user_can( 'read' );
			},
		)
	);
}
