// Add the Rating column immediately before the Date column.
add_filter( 'manage_wpbp_book_posts_columns', function ( $columns ) {
	$new_columns = array();
	$inserted    = false;

	foreach ( $columns as $key => $label ) {
		if ( 'date' === $key && ! $inserted ) {
			$new_columns['wpbp_rating'] = __( 'Rating', 'wpbp' );
			$inserted                   = true;
		}
		$new_columns[ $key ] = $label;
	}

	if ( ! $inserted ) {
		$new_columns['wpbp_rating'] = __( 'Rating', 'wpbp' );
	}

	return $new_columns;
} );

// Print the stored rating in the column cell.
add_action( 'manage_wpbp_book_posts_custom_column', function ( $column, $post_id ) {
	if ( 'wpbp_rating' !== $column ) {
		return;
	}

	$rating = get_post_meta( $post_id, 'wpbp_rating', true );
	echo esc_html( '' !== $rating ? $rating : '' );
}, 10, 2 );

// Register the column as sortable.
add_filter( 'manage_edit-wpbp_book_sortable_columns', function ( $columns ) {
	$columns['wpbp_rating'] = 'wpbp_rating';
	return $columns;
} );

// Sort numerically by the rating meta value when requested.
add_action( 'pre_get_posts', function ( $query ) {
	if ( ! is_admin() || ! $query->is_main_query() ) {
		return;
	}

	if ( 'wpbp_book' !== $query->get( 'post_type' ) ) {
		return;
	}

	if ( 'wpbp_rating' !== $query->get( 'orderby' ) ) {
		return;
	}

	$query->set( 'meta_key', 'wpbp_rating' );
	$query->set( 'orderby', 'meta_value_num' );
} );
