add_action( 'wp_ajax_wpbp_toggle_featured', 'wpbp_handle_toggle_featured' );

function wpbp_handle_toggle_featured() {
	if ( ! is_user_logged_in() ) {
		wp_send_json_error( array( 'message' => 'Not authenticated.' ), 401 );
	}

	if ( ! check_ajax_referer( 'wpbp_toggle', '_ajax_nonce', false ) ) {
		wp_send_json_error( array( 'message' => 'Invalid nonce.' ), 403 );
	}

	$post_id = isset( $_POST['post_id'] ) ? absint( wp_unslash( $_POST['post_id'] ) ) : 0;

	if ( $post_id <= 0 || ! get_post( $post_id ) ) {
		wp_send_json_error( array( 'message' => 'Invalid post.' ), 400 );
	}

	if ( ! current_user_can( 'edit_post', $post_id ) ) {
		wp_send_json_error( array( 'message' => 'You are not allowed to edit this post.' ), 403 );
	}

	$current = get_post_meta( $post_id, 'wpbp_featured', true );
	$is_on   = ( '1' === (string) $current );
	$new     = $is_on ? '0' : '1';

	update_post_meta( $post_id, 'wpbp_featured', $new );

	wp_send_json_success(
		array(
			'featured' => $is_on ? 'off' : 'on',
		)
	);
}
