function wpbp_isbn_render_meta_box( $post ) {
	$isbn = get_post_meta( $post->ID, '_wpbp_isbn', true );

	wp_nonce_field( 'wpbp_isbn_save', 'wpbp_isbn_nonce' );
	printf(
		'<input type="text" id="wpbp_isbn" name="wpbp_isbn" value="%s" class="widefat" />',
		esc_attr( $isbn )
	);
}

function wpbp_isbn_save_meta( $post_id, $post, $update ) {
	if ( ! isset( $_POST['wpbp_isbn_nonce'] ) ) {
		return;
	}

	$nonce = sanitize_text_field( wp_unslash( $_POST['wpbp_isbn_nonce'] ) );
	if ( ! wp_verify_nonce( $nonce, 'wpbp_isbn_save' ) ) {
		return;
	}

	if ( ! current_user_can( 'edit_post', $post_id ) ) {
		return;
	}

	if ( wp_is_post_revision( $post_id ) ) {
		return;
	}

	if ( wp_is_post_autosave( $post_id ) || ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) ) {
		return;
	}

	if ( ! isset( $_POST['wpbp_isbn'] ) ) {
		return;
	}

	$isbn = trim( wp_strip_all_tags( wp_unslash( $_POST['wpbp_isbn'] ) ) );

	update_post_meta( $post_id, '_wpbp_isbn', $isbn );
}

