<?php

function wpbp_register_archive_bulk_action( $bulk_actions ) {
	$bulk_actions['wpbp_archive'] = __( 'Archive', 'wpbp' );
	return $bulk_actions;
}

function wpbp_handle_archive_bulk_action( $redirect_url, $doaction, $post_ids ) {
	if ( 'wpbp_archive' !== $doaction ) {
		return $redirect_url;
	}

	$archived = 0;

	foreach ( (array) $post_ids as $post_id ) {
		$post_id = absint( $post_id );

		if ( ! $post_id || 'wpbp_book' !== get_post_type( $post_id ) ) {
			continue;
		}

		if ( ! current_user_can( 'edit_post', $post_id ) ) {
			continue;
		}

		$result = update_post_meta( $post_id, 'wpbp_archived', 1 );

		if ( false !== $result || '1' === (string) get_post_meta( $post_id, 'wpbp_archived', true ) ) {
			$archived++;
		}
	}

	return add_query_arg( 'wpbp_archived', $archived, $redirect_url );
}

add_filter( 'bulk_actions-edit-wpbp_book', 'wpbp_register_archive_bulk_action' );
