if ( ! function_exists( 'wpbp_backup_freshness_test' ) ) {
	/**
	 * Runs the backup freshness check directly on the Site Health screen.
	 *
	 * @return array
	 */
	function wpbp_backup_freshness_test() {
		$last_backup  = get_option( 'wpbp_last_backup' );
		$week_seconds = 7 * DAY_IN_SECONDS;
		$is_fresh     = false;

		if ( false !== $last_backup && is_numeric( $last_backup ) && (int) $last_backup > 0 ) {
			$age      = time() - (int) $last_backup;
			$is_fresh = ( $age >= 0 && $age < $week_seconds );
		}

		if ( $is_fresh ) {
			$result = array(
				'label'       => __( 'A recent backup exists' ),
				'status'      => 'good',
				'badge'       => array(
					'label' => __( 'Backups' ),
					'color' => 'blue',
				),
				'description' => '<p>' . __( 'The most recent backup was created within the last seven days.' ) . '</p>',
				'actions'     => '',
				'test'        => 'wpbp_backup_freshness',
			);
		} else {
			$result = array(
				'label'       => __( 'No recent backup found' ),
				'status'      => 'recommended',
				'badge'       => array(
					'label' => __( 'Backups' ),
					'color' => 'blue',
				),
				'description' => '<p>' . __( 'No backup has been recorded in the last seven days. Create a backup to protect your site data.' ) . '</p>',
				'actions'     => '',
				'test'        => 'wpbp_backup_freshness',
			);
		}

		return $result;
