function wpbp_block_registration_domains( $errors, $sanitized_user_login, $user_email ) {
	if ( ! $errors instanceof WP_Error ) {
		$errors = new WP_Error();
	}

	$blocked = get_option( 'wpbp_blocked_domains', array() );
	if ( ! is_array( $blocked ) || empty( $blocked ) ) {
		return $errors;
	}

	$email = strtolower( trim( (string) $user_email ) );
	$pos   = strrpos( $email, '@' );
	if ( false === $pos ) {
		return $errors;
	}

	$domain = substr( $email, $pos + 1 );

	$blocked_domains = array_map(
		static function ( $item ) {
			return strtolower( trim( (string) $item ) );
		},
		$blocked
	);

	if ( '' !== $domain && in_array( $domain, $blocked_domains, true ) ) {
		$errors->add(
			'wpbp_blocked_domain',
			__( '<strong>Error</strong>: Registration with this email domain is not allowed.', 'default' )
		);
	}

	return $errors;
}
