add_filter(
    'login_redirect',
    function ( $redirect_to, $requested_redirect_to, $user ) {
        // Failed sign-ins (WP_Error) or anything that is not a user: leave the destination unchanged.
        if ( ! ( $user instanceof WP_User ) ) {
            return $redirect_to;
        }

        // Administrators keep the requested destination; otherwise WordPress's default stands.
        if ( user_can( $user, 'manage_options' ) ) {
            if ( ! empty( $requested_redirect_to ) ) {
                return $requested_redirect_to;
            }
            return $redirect_to;
        }

        // Editors without option management go to the post list.
        if ( user_can( $user, 'edit_posts' ) ) {
            return admin_url( 'edit.php' );
        }

        // Everyone else goes to the site's front page.
        return home_url();
    },
    10,
    3
);
