 *
 * Nothing in here reads or executes the pattern file; the markup object only
 * runs the file the first time its string value is needed.
 */
function wpbp_hero_register_patterns() {
	if ( class_exists( 'WP_Block_Pattern_Categories_Registry' ) && function_exists( 'register_block_pattern_category' ) ) {
		if ( ! WP_Block_Pattern_Categories_Registry::get_instance()->is_registered( 'featured' ) ) {
			register_block_pattern_category(
