				array( 'label' => __( 'Featured', 'wpbp-hero' ) )
			);
		}
	}

	if ( ! function_exists( 'register_block_pattern' ) ) {
		return;
	}

	if ( class_exists( 'WP_Block_Patterns_Registry' ) && WP_Block_Patterns_Registry::get_instance()->is_registered( 'wpbp/hero' ) ) {
		return;
	}

	register_block_pattern(
		'wpbp/hero',
		array(
			'title'       => __( 'WPBP Hero', 'wpbp-hero' ),
			'description' => __( 'A hero section with the site name and a welcome message.', 'wpbp-hero' ),
			'categories'  => array( 'featured' ),
			'content'     => new WPBP_Hero_Lazy_Content( WPBP_HERO_DIR . 'patterns/hero.php' ),
		)
	);
}

