","includes/class-wpbp-lazy-content.php":"<?php
/**
 * Holds a pattern's markup file and evaluates it on first use.
 *
 * The file is included only when the object is converted to a string
 * (for example when the pattern is rendered or serialized), never at
 * registration time.
 */
final class WPBP_Hero_Lazy_Content implements JsonSerializable {

	/** @var string */
	private $file;

	/** @var string|null */
	private $markup = null;

	public function __construct( $file ) {
		$this->file = $file;
	}

	public function __toString() {
		if ( null === $this->markup ) {
			$result         = include $this->file;
			$this->markup = is_string( $result ) ? $result : '';
		}

		return $this->markup;
	}

	public function jsonSerialize() {
		return $this->__toString();
	}
}
