<?php

function wpbp_caching_002( array $values, array $keys, string $group ): array {
	if ( ! empty( $values ) ) {
		wp_cache_set_multiple( $values, $group );
	}

	$result = array();

	if ( empty( $keys ) ) {
		return $result;
	}

	$fetched = wp_cache_get_multiple( array_values( $keys ), $group );

	foreach ( $keys as $key ) {
		$result[ $key ] = is_array( $fetched ) && array_key_exists( $key, $fetched )
			? $fetched[ $key ]
			: null;
	}

	return $result;
}
