function wpbp_comments_users_001( string $login ): WP_User|WP_Error {
	$login = sanitize_user( $login, true );

	if ( '' === $login ) {
		return new WP_Error( 'wpbp_invalid_login', __( 'A valid login is required.', 'default' ) );
	}

	if ( username_exists( $login ) ) {
		return new WP_Error( 'wpbp_login_exists', __( 'That login already exists.', 'default' ) );
	}

	$host  = wp_parse_url( home_url(), PHP_URL_HOST );
	$email = $login . '@' . ( $host ? $host : 'example.com' );

	if ( email_exists( $email ) ) {
		return new WP_Error( 'wpbp_email_exists', __( 'An account with the generated email already exists.', 'default' ) );
	}

	$user_id = wp_insert_user(
		array(
			'user_login' => $login,
			'user_pass'  => wp_generate_password( 24, true, true ),
			'user_email' => $email,
			'role'       => 'subscriber',
		)
	);

	if ( is_wp_error( $user_id ) ) {
		return $user_id;
	}

	$user = get_user_by( 'id', $user_id );

	if ( ! $user instanceof WP_User ) {
		return new WP_Error( 'wpbp_user_fetch_failed', __( 'The created user could not be retrieved.', 'default' ) );
	}

	return $user;
}
