/**
 * Submit a visitor comment through WordPress's comment flow.
 *
 * Runs WordPress's comment checks (duplicate detection, flood control,
 * moderation) and returns the new comment ID on success, or the WP_Error
 * object WordPress produced on rejection, without ending the request.
 *
 * @param array $comment_data Keys: comment_post_ID, comment_author,
 *                            comment_author_email, comment_author_url,
 *                            comment_content.
 * @return int|WP_Error New comment ID, or WP_Error on rejection.
 */
function wpbp_comments_users_005( array $comment_data ) {
	$server_ip  = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';
	$user_agent = isset( $_SERVER['HTTP_USER_AGENT'] ) ? substr( sanitize_text_field( wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) ), 0, 254 ) : '';

	$commentdata = array(
		'comment_post_ID'      => isset( $comment_data['comment_post_ID'] ) ? absint( $comment_data['comment_post_ID'] ) : 0,
		'comment_author'       => isset( $comment_data['comment_author'] ) ? sanitize_text_field( $comment_data['comment_author'] ) : '',
		'comment_author_email' => isset( $comment_data['comment_author_email'] ) ? sanitize_email( $comment_data['comment_author_email'] ) : '',
		'comment_author_url'   => isset( $comment_data['comment_author_url'] ) ? esc_url_raw( $comment_data['comment_author_url'] ) : '',
		'comment_content'      => isset( $comment_data['comment_content'] ) ? (string) $comment_data['comment_content'] : '',
		'comment_parent'       => 0,
		'comment_type'         => '',
		'comment_author_IP'    => $server_ip,
		'comment_agent'        => $user_agent,
		'user_ID'              => get_current_user_id(),
	);

	// Second argument true: return WP_Error instead of calling wp_die().
	$result = wp_new_comment( $commentdata, true );

	if ( is_wp_error( $result ) ) {
		return $result;
	}

	return (int) $result;
}
