function wpbp_comments_users_006( int $user_id, string $new_password, string $session_token ): bool {
	if ( $user_id <= 0 || '' === $new_password || '' === $session_token ) {
		return false;
	}

	$user = get_userdata( $user_id );
	if ( ! $user ) {
		return false;
	}

	// Hashes the password via the WordPress user API before storing it.
	wp_set_password( $new_password, $user_id );
	clean_user_cache( $user_id );

	// Confirm WordPress accepted the change by verifying the stored hash.
	$updated = get_userdata( $user_id );
	if ( ! $updated || ! wp_check_password( $new_password, $updated->user_pass, $user_id ) ) {
		return false;
	}

	// Revoke all of this user's other sessions, keeping the supplied token valid.
	// Session storage is scoped to $user_id, so other users' sessions are not affected.
	$session_manager = WP_Session_Tokens::get_instance( $user_id );
	$session_manager->destroy_others( $session_token );

	return true;
}
