if ( ! function_exists( 'wpbp_comments_users_007_prune' ) ) {
	/**
	 * Recursively keeps only approved descendants of a comment.
	 *
	 * @param WP_Comment $comment Approved comment.
	 * @return WP_Comment
	 */
	function wpbp_comments_users_007_prune( WP_Comment $comment ): WP_Comment {
		$approved_children = [];

		foreach ( (array) $comment->get_children() as $child ) {
			if ( ! $child instanceof WP_Comment ) {
				continue;
			}
			if ( (string) $child->comment_approved !== '1' ) {
				continue;
			}
			$approved_children[] = wpbp_comments_users_007_prune( $child );
		}

		$comment->children = $approved_children;

		return $comment;
	}
}

if ( ! function_exists( 'wpbp_comments_users_007' ) ) {
	/**
	 * Returns the approved comment tree for a post.
	 *
	 * @param int $post_id Post ID.
	 * @return array Top-level approved WP_Comment objects, each with approved replies in ->children.
	 */
	function wpbp_comments_users_007( int $post_id ): array {
		$post_id = absint( $post_id );

		if ( $post_id <= 0 ) {
			return [];
		}

		$query = new WP_Comment_Query(
			[
				'post_id'       => $post_id,
				'status'        => 'approve',
				'parent'        => 0,
				'hierarchical'  => 'threaded',
				'orderby'       => 'comment_date_gmt',
				'order'         => 'ASC',
				'no_found_rows' => true,
			]
		);

		$top_level = is_array( $query->comments ) ? $query->comments : [];
		$tree      = [];

		foreach ( $top_level as $comment ) {
			if ( ! $comment instanceof WP_Comment ) {
				continue;
			}
			if ( (int) $comment->comment_post_ID !== $post_id ) {
				continue;
			}
			if ( (string) $comment->comment_approved !== '1' ) {
				continue;
			}
			$tree[] = wpbp_comments_users_007_prune( $comment );
		}

		return $tree;
	}
}

