<?php
/**
 * Returns the sorted IDs of every registered connector of the given type.
 *
 * @param string $type The connector type to filter by.
 * @return array Alphabetically sorted connector IDs.
 */
function wpbp_connectors_api_006( string $type ): array {
	if ( ! function_exists( 'wp_get_connectors' ) ) {
		return array();
	}

	$ids = array();

	foreach ( (array) wp_get_connectors() as $key => $connector ) {
		$connector_type = null;
		$connector_id   = (string) $key;

		if ( is_array( $connector ) ) {
			$connector_type = $connector['type'] ?? null;
			$connector_id   = isset( $connector['id'] ) ? (string) $connector['id'] : $connector_id;
		} elseif ( is_object( $connector ) ) {
			$connector_type = $connector->type ?? null;
			$connector_id   = isset( $connector->id ) ? (string) $connector->id : $connector_id;
		}

		if ( $connector_type !== $type ) {
			continue;
		}

		$ids[] = $connector_id;
	}

	sort( $ids, SORT_STRING );

	return $ids;
}
