    $modified         = $original;
    $modified['name'] = 'WPBP Antispam';

    $registered = wp_register_connector( $connector_id, $modified );

    if ( ! $registered ) {
        // Roll back to the original connector so the site is not left without it.
        wp_register_connector( $connector_id, $original );
        return false;
    }

    return true;
}
