function wpbp_database_007( string $table_suffix, string $search ): int {
	global $wpdb;

	// The table name cannot be parameterized, so restrict the suffix to safe identifier characters.
	if ( ! preg_match( '/^[A-Za-z0-9_]+$/', $table_suffix ) ) {
		return 0;
