/**
 * Registers a PHP-only server-side block named 'wpbp/auto'.
 *
 * The block has a string "message" attribute (default 'Hi') and renders
 * that message on the server. No editor script is required, so the block
 * is picked up by the editor from its server-side registration.
 *
 * WordPress has already finished booting, so registration happens immediately.
 *
 * @return bool True if the block is registered with WordPress, false otherwise.
 */
function wpbp_gb_block_api_002(): bool {
	if ( ! function_exists( 'register_block_type' ) || ! class_exists( 'WP_Block_Type_Registry' ) ) {
		return false;
	}

	$registry = WP_Block_Type_Registry::get_instance();

	if ( $registry->is_registered( 'wpbp/auto' ) ) {
		return true;
	}

	$block_type = register_block_type(
		'wpbp/auto',
		array(
			'api_version'     => 3,
			'title'           => 'Auto',
			'description'     => 'A PHP-only block that renders a message on the server.',
			'category'        => 'widgets',
			'icon'            => 'smiley',
			'supports'        => array(
				'html' => false,
			),
			'attributes'      => array(
				'message' => array(
					'type'    => 'string',
					'default' => 'Hi',
				),
			),
			'render_callback' => static function ( array $attributes, string $content = '', $block = null ): string {
				$message = isset( $attributes['message'] ) && is_string( $attributes['message'] )
					? $attributes['message']
					: 'Hi';

				return sprintf(
					'<div class="wp-block-wpbp-auto">%s</div>',
					esc_html( $message )
				);
			},
		)
	);

	return $block_type instanceof WP_Block_Type;
}
