function wpbp_gb_block_api_003( string $content ): array {
	$counts = array();

	if ( '' === trim( $content ) ) {
		return $counts;
	}

	if ( ! class_exists( 'WP_Block_Processor' ) ) {
		return $counts;
	}

	$processor = new WP_Block_Processor( $content );

	while ( $processor->next_delimiter() ) {
		if ( $processor->is_block_closer() ) {
			continue;
		}

		$block_name = $processor->get_block_type();

		if ( ! is_string( $block_name ) || '' === $block_name ) {
			continue;
		}

		if ( false === strpos( $block_name, '/' ) ) {
			$block_name = 'core/' . $block_name;
		}

		$counts[ $block_name ] = ( $counts[ $block_name ] ?? 0 ) + 1;
	}

	return $counts;
