function wpbp_block_api_009(): bool {
	$render = static function ( $attributes, $content, $block ) {
		$text = ( isset( $attributes['text'] ) && is_string( $attributes['text'] ) )
			? $attributes['text']
			: 'Promo';

		$wrapper = get_block_wrapper_attributes( array( 'data-promo' => '1' ) );

		$tags = new WP_HTML_Tag_Processor( '<div ' . $wrapper . '>' );

		if ( $tags->next_tag( 'div' ) ) {
			$existing = $tags->get_attribute( 'class' );
			$classes  = is_string( $existing )
				? preg_split( '/\s+/', trim( $existing ), -1, PREG_SPLIT_NO_EMPTY )
				: array();

			$classes = array_values( array_unique( array_merge( array( 'promo' ), $classes ) ) );
			$tags->set_attribute( 'class', implode( ' ', $classes ) );
		}

		return $tags->get_updated_html() . esc_html( $text ) . '</div>';
	};

	$block_type = register_block_type(
		'wpbp/promo',
		array(
			'api_version'     => 3,
			'title'           => 'Promo',
