    $pattern = '/<!--\s*(\/)?wp:([a-z0-9][a-z0-9_-]*(?:\/[a-z0-9][a-z0-9_-]*)?)(?:\s+(\{.*?\}))?\s*(\/)?-->/s';

    if ( ! preg_match_all( $pattern, $document, $matches, PREG_SET_ORDER ) ) {
        return [];
    }

    $stack = [];
    $ids   = [];

    foreach ( $matches as $match ) {
        $is_closing     = isset( $match[1] ) && $match[1] === '/';
        $name           = $match[2];
        $is_self_closing = isset( $match[4] ) && $match[4] === '/';

        // Normalise: an explicit core namespace is the same as no namespace.
        if ( strpos( $name, 'core/' ) === 0 ) {
            $name = substr( $name, 5 );
        }

        if ( $is_closing ) {
            if ( ! empty( $stack ) ) {
                array_pop( $stack );
            }
            continue;
        }

        $parent = empty( $stack ) ? null : $stack[ count( $stack ) - 1 ];

        if ( $name === 'image' && $parent === 'gallery' ) {
            $attrs = ( isset( $match[3] ) && $match[3] !== '' )
                ? json_decode( $match[3], true )
