<?php

function wpbp_gb_block_bindings_005( int $post_id ): string {
	$post_id = absint( $post_id );

	// Register the shelf code meta so the core post meta binding source may read it.
	$registered_keys = get_registered_meta_keys( 'post', 'wpbp_book' );
	if ( ! isset( $registered_keys['wpbp_shelf_code'] ) ) {
		register_post_meta(
			'wpbp_book',
			'wpbp_shelf_code',
			array(
				'type'         => 'string',
				'single'       => true,
				'show_in_rest' => true,
			)
		);
	}

	$markup = '<!-- wp:list -->'
		. '<ul class="wp-block-list"><!-- wp:list-item {"metadata":{"bindings":{"content":{"source":"core/post-meta","args":{"key":"wpbp_shelf_code"}}}}} -->'
		. '<li>Unknown</li>'
		. '<!-- /wp:list-item --></ul>'
		. '<!-- /wp:list -->';

	$parsed_blocks = parse_blocks( $markup );
	$list_block    = null;
	foreach ( $parsed_blocks as $parsed_block ) {
		if ( ! empty( $parsed_block['blockName'] ) ) {
			$list_block = $parsed_block;
			break;
		}
	}

	if ( null === $list_block ) {
		return '';
	}

	// Provide the post context the binding source needs.
	$context = array(
		'postId'   => $post_id,
		'postType' => 'wpbp_book',
	);

	$block = new WP_Block( $list_block, $context );

	return (string) $block->render();
}
