				$style_attributes = array();

				if ( isset( $attributes['style']['dimensions'] ) && is_array( $attributes['style']['dimensions'] ) ) {
					$dimensions = $attributes['style']['dimensions'];

					if ( ! empty( $dimensions['width'] ) ) {
						$style_attributes[] = 'width:' . esc_attr( $dimensions['width'] );
					}

					if ( ! empty( $dimensions['height'] ) ) {
						$style_attributes[] = 'height:' . esc_attr( $dimensions['height'] );
					}
