	$ignored = array();
	foreach ( parse_blocks( $updated ) as $block ) {
		if (
			isset( $block['attrs']['metadata']['ignoredHookedBlocks'] ) &&
			is_array( $block['attrs']['metadata']['ignoredHookedBlocks'] )
		) {
			foreach ( $block['attrs']['metadata']['ignoredHookedBlocks'] as $name ) {
				if ( is_string( $name ) && '' !== $name ) {
					$ignored[] = $name;
				}
			}
		}
	}

	return array(
		'content' => $updated,
		'ignored' => array_values( array_unique( $ignored ) ),
	);
}
