<?php
function wpbp_gb_markup_008(): string {
    // Attributes that the core/table block saves, with their block.json defaults.
    $attributes = array(
        'hasFixedLayout' => false,
        'backgroundColor' => null,
        'caption'         => '',
    );
    $defaults = array(
        'hasFixedLayout' => false,
        'backgroundColor' => null,
        'caption'         => '',
    );

    // Only serialize attributes that differ from their defaults.
    $non_default = array();
    foreach ( $attributes as $key => $value ) {
        if ( ! array_key_exists( $key, $defaults ) || $value !== $defaults[ $key ] ) {
            $non_default[ $key ] = $value;
        }
    }

    $comment_attrs = '';
    if ( ! empty( $non_default ) ) {
        $comment_attrs = ' ' . wp_json_encode( $non_default, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE );
    }

    $head = array(
        array( 'Plan', 'Price' ),
    );
    $body = array(
        array( 'Basic', '$10' ),
        array( 'Pro', '$20' ),
    );

    $render_row = static function ( array $cells, string $tag ): string {
        $html = '<tr>';
        foreach ( $cells as $cell ) {
            $html .= '<' . $tag . '>' . esc_html( $cell ) . '</' . $tag . '>';
        }
        return $html . '</tr>';
    };

    $table = '<table>';
    $table .= '<thead>';
    foreach ( $head as $row ) {
        $table .= $render_row( $row, 'th' );
    }
    $table .= '</thead>';

    $table .= '<tbody>';
    foreach ( $body as $row ) {
        $table .= $render_row( $row, 'td' );
    }
    $table .= '</tbody>';
    $table .= '</table>';

    $figure = '<figure class="wp-block-table">' . $table . '</figure>';

    return '<!-- wp:table' . $comment_attrs . " -->\n"
        . $figure . "\n"
        . '<!-- /wp:table -->';
}
