<?php

function wpbp_gb_interactivity_api_006( string $store_namespace, array $items ): string {
	$store_namespace = trim( $store_namespace );

	$template = '<ul data-wp-interactive="' . esc_attr( $store_namespace ) . '">'
		. '<template data-wp-each="state.items">'
		. '<li data-wp-text="context.item"></li>'
		. '</template>'
		. '</ul>';

	// Only a sequential list of plain strings can be repeated by the server-side each directive.
	$is_list = array_values( $items ) === $items;
	$all_strings = $is_list && array_reduce(
		$items,
		static function ( bool $carry, $value ): bool {
			return $carry && is_string( $value );
		},
		true
	);

	if ( '' === $store_namespace || ! $all_strings || ! function_exists( 'wp_interactivity_process_directives' ) || ! function_exists( 'wp_interactivity_state' ) ) {
		// WordPress cannot repeat this list on the server; leave the template untouched.
		return $template;
	}

	// Register the items as store state under the `items` key.
	wp_interactivity_state( $store_namespace, array( 'items' => $items ) );

	// Let WordPress expand the template during server-side directive processing.
	return wp_interactivity_process_directives( $template );
}
