<?php

function wpbp_hooks_003( callable $callback ): bool {
    $hook     = 'wpbp_remove_filter';
    $priority = 0;

    // has_filter() returns the priority (int) or false. Priority 0 is falsy,
    // so a strict comparison is required.
    $was_present = ( $priority === has_filter( $hook, $callback ) );

    if ( ! $was_present ) {
        return false;
    }

    remove_filter( $hook, $callback, $priority );

    $is_absent = ( $priority !== has_filter( $hook, $callback ) );

    return $was_present && $is_absent;
}
