/**
 * Returns the normalized form of a post content fragment, as a browser would
 * understand it, using the WordPress HTML API in body context.
 *
 * @param string $html Raw HTML fragment.
 * @return string Serialized, normalized markup.
 */
function wpbp_html_api_007( string $html ): string {
	if ( ! class_exists( 'WP_HTML_Processor' ) ) {
		return '';
	}

	// Parse the fragment in the body context (the default for create_fragment()).
	$processor = WP_HTML_Processor::create_fragment( $html, '<body>' );

	if ( null === $processor ) {
		return '';
	}

	// Run the parser to completion so implied elements, comment rewriting,
	// text re-encoding and discarding of unterminated syntax are all applied.
	while ( $processor->next_token() ) {
		continue;
	}

	$serialized = $processor->serialize();

	return null === $serialized ? '' : $serialized;
}
