	if ( 200 !== $status ) {
		return array(
			'outcome' => 'http_error',
			'code'    => $status,
			'data'    => null,
		);
	}

	$body    = wp_remote_retrieve_body( $response );
	$decoded = json_decode( $body, true );

	return array(
		'outcome' => 'ok',
		'code'    => $status,
		'data'    => is_array( $decoded ) ? $decoded : array(),
	);
}
