function wpbp_http_api_004( string $url ): array {
	$result = array(
		'type'  => '',
		'rate'  => 0,
		'links' => array(),
		'code'  => 0,
	);

	$response = wp_remote_get( $url );

	if ( is_wp_error( $response ) ) {
		return $result;
	}

	$code = wp_remote_retrieve_response_code( $response );
	$result['code'] = (int) $code;

	$type = wp_remote_retrieve_header( $response, 'content-type' );
	if ( is_array( $type ) ) {
		$type = reset( $type );
	}
	$result['type'] = is_string( $type ) ? $type : '';

	$rate = wp_remote_retrieve_header( $response, 'x-wpbp-rate' );
	if ( is_array( $rate ) ) {
		$rate = reset( $rate );
	}
	$result['rate'] = (int) $rate;

	$link = wp_remote_retrieve_header( $response, 'link' );
	$links = array();

	if ( is_array( $link ) ) {
		foreach ( $link as $value ) {
			if ( is_string( $value ) && '' !== trim( $value ) ) {
				$links[] = trim( $value );
			}
		}
	} elseif ( is_string( $link ) && '' !== trim( $link ) ) {
		// Multiple Link headers may be joined with ", " by the HTTP layer.
		// Each Link value begins with "<", so split only before those.
		$parts = preg_split( '/,\s*(?=<)/', $link );
		foreach ( $parts as $part ) {
			$part = trim( $part );
			if ( '' !== $part ) {
				$links[] = $part;
			}
		}
	}

	$result['links'] = $links;

	return $result;
}
