<?php
/**
 * Temporarily switches WordPress to the supplied locale, then restores the previous locale.
 *
 * @param string $locale The locale to switch to (e.g. 'de_DE', 'fr_FR').
 * @return bool True if the switch succeeded, false otherwise.
 */
function wpbp_internationalization_003( string $locale ): bool {
	if ( ! function_exists( 'switch_to_locale' ) || ! function_exists( 'restore_previous_locale' ) ) {
		return false;
	}

	$locale = trim( $locale );

	if ( '' === $locale ) {
		return false;
	}

	$switched = false;

	try {
		$switched = switch_to_locale( $locale );
	} catch ( \Throwable $e ) {
		$switched = false;
	}

	if ( $switched ) {
		restore_previous_locale();
	}

	return (bool) $switched;
}
