<?php

function wpbp_mail_url_001( string $url ): string {
	$url = trim( $url );

	if ( '' === $url ) {
		return '';
	}

	if ( 0 === strpos( $url, '//' ) ) {
		// Protocol-relative URL: prefer HTTPS.
		$url = 'https:' . $url;
	} elseif ( ! preg_match( '~^[a-z][a-z0-9+.\-]*://~i', $url ) && ! preg_match( '~^[/?#]~', $url ) ) {
		// Missing scheme: prefer HTTPS over WordPress's default HTTP.
		$url = 'https://' . $url;
	}

	return esc_url_raw( $url, array( 'https', 'http' ) );
}
