<?php

function wpbp_mail_url_005( string $to, string $subject, string $message, array $cc, string $reply_to ): bool {
    $to = sanitize_email( $to );
    if ( ! is_email( $to ) ) {
        return false;
    }

    $reply_to = sanitize_email( $reply_to );
    if ( ! is_email( $reply_to ) ) {
        return false;
    }

    $cc_valid = array();
    foreach ( $cc as $address ) {
        if ( ! is_string( $address ) ) {
            continue;
        }
        $address = sanitize_email( $address );
        if ( is_email( $address ) && $address !== $to && ! in_array( $address, $cc_valid, true ) ) {
            $cc_valid[] = $address;
        }
    }

    $headers = array(
        'Content-Type: text/plain; charset=UTF-8',
        'Reply-To: ' . $reply_to,
    );

    if ( ! empty( $cc_valid ) ) {
        $headers[] = 'Cc: ' . implode( ', ', $cc_valid );
    }

    return (bool) wp_mail( $to, $subject, $message, $headers );
}
