function wpbp_mail_url_006( string $to, string $subject, string $message, string $from_email, string $from_name, string $attachment ): bool {
	if ( ! is_readable( $attachment ) ) {
		return false;
	}

	$email_filter = static function () use ( $from_email ) {
		return $from_email;
	};

	$name_filter = static function () use ( $from_name ) {
		return $from_name;
	};

	add_filter( 'wp_mail_from', $email_filter, 99 );
	add_filter( 'wp_mail_from_name', $name_filter, 99 );

	try {
		$sent = wp_mail( $to, $subject, $message, array(), array( $attachment ) );
	} finally {
		remove_filter( 'wp_mail_from', $email_filter, 99 );
		remove_filter( 'wp_mail_from_name', $name_filter, 99 );
	}

	return (bool) $sent;
}
