	/**
	 * Returns WordPress image source data for an attachment.
	 *
	 * @param int          $attachment_id Attachment post ID.
	 * @param string|array $size          Registered image size name or [ width, height ] array.
	 * @return array|false Array of [ url, width, height, is_intermediate ] or false on failure.
	 */
	function wpbp_media_001( int $attachment_id, string|array $size = 'thumbnail' ): array|false {
