	'wpbp-leaf',
	content_url( 'wpbp/leaf.js' ),
	array( 'wpbp-mid' ),
	'1.0.0',
	array( 'in_footer' => true )
);

// Request the defer loading strategy for each script in the chain (WordPress 6.3+).
wp_script_add_data( 'wpbp-base', 'strategy', 'defer' );
wp_script_add_data( 'wpbp-mid', 'strategy', 'defer' );
wp_script_add_data( 'wpbp-leaf', 'strategy', 'defer' );

// Make wpbpLeafConfig exist before the leaf script runs.
// An inline script placed "before" the leaf script is printed immediately ahead of its tag,
// so it executes during parsing, before the deferred leaf script.
wp_add_inline_script(
	'wpbp-leaf',
	'var wpbpLeafConfig = ' . wp_json_encode( array( 'token' => 'wpbp-token-42' ) ) . ';',
	'before'
);

// Enqueue the chain directly, since the site has already booted.
wp_enqueue_script( 'wpbp-leaf' );
