/**
 * Plugin Name: WPBP Reader Settings
 * Description: Stores, upgrades and cleans up the WPBP reader settings.
 * Version: 2.0.0
 * Text Domain: wpbp-reader-settings
 */

if (!defined('ABSPATH')) {
    exit;
}

define('WPBP_READER_SETTINGS_VERSION', 2);
define('WPBP_READER_SETTINGS_OPTION', 'wpbp_reader_settings');
define('WPBP_READER_UPGRADES_OPTION', 'wpbp_reader_upgrades');

/**
 * Default settings for the current version.
 *
 * @return array
 */
function wpbp_reader_default_settings() {
    return array(
        'version'      => WPBP_READER_SETTINGS_VERSION,
        'per_page'     => 10,
        'show_covers'  => true,
    );
}

/**
 * Activation routine: seeds defaults only when no settings are stored yet.
 */
function wpbp_reader_activate() {
    $missing = new stdClass();
    $existing = get_option(WPBP_READER_SETTINGS_OPTION, $missing);

    if ($existing === $missing) {
        add_option(WPBP_READER_SETTINGS_OPTION, wpbp_reader_default_settings());
    }
}
register_activation_hook(__FILE__, 'wpbp_reader_activate');

/**
 * Upgrades stored settings that are older than the current version.
 * Version 1 stored a single perPage entry; its page size is carried over.
 */
function wpbp_reader_maybe_upgrade() {
    $settings = get_option(WPBP_READER_SETTINGS_OPTION, null);

    if (!is_array($settings)) {
        return;
    }

    $stored_version = isset($settings['version']) ? (int) $settings['version'] : 1;

    if ($stored_version >= WPBP_READER_SETTINGS_VERSION) {
        return;
    }

    $defaults = wpbp_reader_default_settings();

    if (isset($settings['perPage'])) {
        $per_page = absint($settings['perPage']);
    } elseif (isset($settings['per_page'])) {
        $per_page = absint($settings['per_page']);
    } else {
        $per_page = 0;
    }

    if ($per_page < 1) {
        $per_page = $defaults['per_page'];
    }

    $upgraded = $settings;
    unset($upgraded['perPage']);

    $upgraded['version']  = WPBP_READER_SETTINGS_VERSION;
    $upgraded['per_page'] = $per_page;

    if (!isset($upgraded['show_covers'])) {
        $upgraded['show_covers'] = $defaults['show_covers'];
    }

    update_option(WPBP_READER_SETTINGS_OPTION, $upgraded);

    $count = (int) get_option(WPBP_READER_UPGRADES_OPTION, 0);
    update_option(WPBP_READER_UPGRADES_OPTION, $count + 1);
}
add_action('plugins_loaded', 'wpbp_reader_maybe_upgrade');

/**
 * Uninstall callback: removes all options this plugin created.
 */
function wpbp_reader_uninstall() {
    delete_option(WPBP_READER_SETTINGS_OPTION);
    delete_option(WPBP_READER_UPGRADES_OPTION);
}
register_uninstall_hook(__FILE__, 'wpbp_reader_uninstall');
"}}

