/**
 * Plugin Name: WPBP Reader
 * Plugin URI: https://example.org/wpbp-reader-docs
 * Description: Reader helper plugin that adds Settings and Docs links to its own row on the Plugins screen.
 * Version: 1.0.0
 * Author: Example
 * License: GPL-2.0-or-later
 * Text Domain: wpbp-reader
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

final class WPBP_Reader_Plugin_Row {

	const SETTINGS_PAGE = 'wpbp-reader';
	const DOCS_URL      = 'https://example.org/wpbp-reader-docs';

	/**
	 * Plugin file relative to the plugins directory, e.g. "wpbp-reader/wpbp-reader.php".
	 *
	 * @var string
	 */
	private static $plugin_file = '';

	public static function init() {
		self::$plugin_file = plugin_basename( __FILE__ );

		add_filter( 'plugin_action_links_' . self::$plugin_file, array( __CLASS__, 'filter_action_links' ), 10, 4 );
		add_filter( 'plugin_row_meta', array( __CLASS__, 'filter_row_meta' ), 10, 4 );
	}

	/**
	 * Prepend the Settings link to this plugin's action links only.
	 *
	 * @param array $actions Existing action links.
	 * @return array
	 */
	public static function filter_action_links( $actions, $plugin_file = '', $plugin_data = array(), $context = '' ) {
		if ( ! is_array( $actions ) ) {
			$actions = array();
		}

		$settings_url = admin_url( 'options-general.php?page=' . self::SETTINGS_PAGE );
		$settings     = '<a href="' . esc_url( $settings_url ) . '">' . esc_html__( 'Settings', 'wpbp-reader' ) . '</a>';

		// Left operand wins on key collisions and keeps Settings first.
		return array( 'wpbp-reader-settings' => $settings ) + $actions;
	}

	/**
	 * Append the Docs link to this plugin's row meta only.
	 *
	 * @param array $plugin_meta Existing row meta entries.
	 * @param string $plugin_file Plugin file being rendered.
	 * @return array
	 */
	public static function filter_row_meta( $plugin_meta, $plugin_file = '', $plugin_data = array(), $status = '' ) {
		if ( ! is_array( $plugin_meta ) ) {
			$plugin_meta = array();
		}

		if ( $plugin_file !== self::$plugin_file ) {
			return $plugin_meta;
		}

		$plugin_meta[] = '<a href="' . esc_url( self::DOCS_URL ) . '" target="_blank" rel="noopener noreferrer">' . esc_html__( 'Docs', 'wpbp-reader' ) . '</a>';

		return $plugin_meta;
	}
}

WPBP_Reader_Plugin_Row::init();
