<?php
function wpbp_post_meta_003( int $post_id, string $meta_key, string $value ): bool {
	if ( $post_id <= 0 || '' === $meta_key ) {
		return false;
	}

	// delete_post_meta() only removes rows whose stored value matches $value,
	// but an empty string would match every row for the key, so handle it separately.
	if ( '' !== $value ) {
		return (bool) delete_post_meta( $post_id, $meta_key, $value );
	}

	global $wpdb;

	$meta_ids = $wpdb->get_col(
		$wpdb->prepare(
			"SELECT meta_id FROM {$wpdb->postmeta} WHERE post_id = %d AND meta_key = %s AND meta_value = ''",
			$post_id,
			$meta_key
		)
	);

	if ( empty( $meta_ids ) ) {
		return false;
	}

	$deleted = false;
	foreach ( $meta_ids as $meta_id ) {
		if ( delete_metadata_by_mid( 'post', (int) $meta_id ) ) {
			$deleted = true;
		}
	}

	return $deleted;
}
