	);

	if ( post_type_exists( $post_type ) ) {
		return array(
			'post_type'    => $post_type,
			'registered'   => false,
			'capabilities' => $capabilities,
			'reason'       => 'already_registered',
		);
	}

	$filter = function ( $caps, $cap, $user_id, $args ) use ( $post_type, $plural ) {
		// Custom meta capability: review_wpbp_project maps to editing others' items.
		if ( 'review_' . $post_type === $cap ) {
			return array( 'edit_others_' . $plural );
		}
		return $caps;
	};

	add_filter( 'map_meta_cap', $filter, 10, 4 );

	$args = array(
