		'capability_type' => array( $post_type, $plural ),
		'map_meta_cap'    => true,
		'capabilities'    => $capabilities,
	);

	$result = register_post_type( $post_type, $args );

	$registered = ! is_wp_error( $result );

	if ( ! $registered ) {
		remove_filter( 'map_meta_cap', $filter, 10 );
	}

	// Clean up the registered type and capability filter at the end of the request.
	register_shutdown_function( function () use ( $post_type, $filter ) {
		remove_filter( 'map_meta_cap', $filter, 10 );
		if ( function_exists( 'unregister_post_type' ) && post_type_exists( $post_type ) ) {
			unregister_post_type( $post_type );
		}
	} );

	return array(
		'post_type'    => $post_type,
		'registered'   => $registered,
		'capabilities' => $capabilities,
		'reason'       => $registered ? 'ok' : $result->get_error_message(),
	);
