	$utc_tz    = new DateTimeZone( 'UTC' );
	$utc_obj   = DateTimeImmutable::createFromFormat( 'Y-m-d H:i:s', $utc_datetime, $utc_tz );
	$errors    = DateTimeImmutable::getLastErrors();

	if ( false === $utc_obj || ( is_array( $errors ) && ( $errors['warning_count'] > 0 || $errors['error_count'] > 0 ) ) ) {
		return 0;
	}

	$gmt_string   = $utc_obj->format( 'Y-m-d H:i:s' );
	$timestamp    = $utc_obj->getTimestamp();
	$local_string = get_date_from_gmt( $gmt_string, 'Y-m-d H:i:s' );

	$author_id = get_current_user_id();
	if ( ! $author_id ) {
		$author_id = 1;
	}

	$post_id = wp_insert_post(
		array(
			'post_title'    => $title,
			'post_status'   => 'future',
			'post_type'     => 'post',
			'post_author'   => $author_id,
			'post_date'     => $local_string,
			'post_date_gmt' => $gmt_string,
			'edit_date'     => true,
		),
		true
	);

	if ( is_wp_error( $post_id ) || ! $post_id ) {
		return 0;
	}

	$post_id = (int) $post_id;

	clean_post_cache( $post_id );

	$args = array( $post_id );
	if ( false === wp_next_scheduled( 'publish_future_post', $args ) ) {
		wp_schedule_single_event( $timestamp, 'publish_future_post', $args );
	}

	return $post_id;
}
