add_filter(
	'wp_insert_post_data',
	static function ( $data, $postarr ) {
		if ( ! is_array( $data ) ) {
			return $data;
		}

		$excerpt = isset( $data['post_excerpt'] ) ? (string) $data['post_excerpt'] : '';

		// Keep any excerpt the post was saved with.
		if ( trim( $excerpt ) !== '' ) {
			return $data;
		}

		$content = isset( $data['post_content'] ) ? (string) $data['post_content'] : '';

		// Strip HTML first so the cut point is in plain text.
		$plain = trim( wp_strip_all_tags( $content ) );

		$pos = strpos( $plain, '.' );

		if ( false === $pos ) {
			$derived = $plain;
		} else {
			$derived = substr( $plain, 0, $pos + 1 );
		}

		$data['post_excerpt'] = trim( $derived );

		// Modifying data in this filter does not call wp_insert_post() again,
		// so no further saves are triggered.
		return $data;
	},
	10,
