/**
 * Returns a WP_Query containing only published sticky posts, in sticky order.
 * Does not rely on the home query's sticky prepending.
 *
 * @return WP_Query
 */
function wpbp_queries_012(): WP_Query {
	$sticky_ids = get_option( 'sticky_posts', array() );
	$sticky_ids = is_array( $sticky_ids ) ? array_values( array_unique( array_filter( array_map( 'absint', $sticky_ids ) ) ) ) : array();

	// An ID of 0 matches no posts, producing an empty result when nothing is sticky.
	$post__in = ! empty( $sticky_ids ) ? $sticky_ids : array( 0 );

	$args = array(
		'post_type'           => 'post',
		'post_status'         => 'publish',
		'post__in'            => $post__in,
		'orderby'             => 'post__in',
		'posts_per_page'      => max( 1, count( $post__in ) ),
		'ignore_sticky_posts' => true,
		'no_found_rows'       => true,
	);

	return new WP_Query( $args );
}
