    $logged_out_status = rest_authorization_required_code();

    // Logged-in status: use the current user if one exists, otherwise a real user.
    $logged_in_user_id = $original_user_id;
    if ( ! $logged_in_user_id ) {
        $users = get_users( [
            'number' => 1,
            'fields' => 'ID',
            'orderby' => 'ID',
            'order' => 'ASC',
        ] );
        $logged_in_user_id = ! empty( $users ) ? (int) $users[0] : 0;
    }

    $logged_in_status = null;
    if ( $logged_in_user_id ) {
        wp_set_current_user( $logged_in_user_id );
        $logged_in_status = rest_authorization_required_code();
    }

    // Restore the original request user.
    wp_set_current_user( $original_user_id );

    return [
        'logged_out' => [
            'user_id' => 0,
            'status'  => $logged_out_status,
        ],
        'logged_in'  => [
            'user_id' => $logged_in_user_id ?: null,
            'status'  => $logged_in_status,
        ],
        'current'    => [
            'user_id' => $original_user_id,
            'status'  => rest_authorization_required_code(),
        ],
    ];
}
