<?php
defined( 'ABSPATH' ) || exit;

if ( ! class_exists( 'WPBP_Venues_Controller' ) ) {

	class WPBP_Venues_Controller extends WP_REST_Controller {

		public function __construct() {
			$this->namespace = 'wpbp/v1';
			$this->rest_base = 'venues';
		}

		public function register_routes() {
			register_rest_route(
				$this->namespace,
				'/' . $this->rest_base,
				array(
					array(
						'methods'             => WP_REST_Server::READABLE,
						'callback'            => array( $this, 'get_items' ),
						'permission_callback' => array( $this, 'get_items_permissions_check' ),
						'args'                => $this->get_collection_params(),
					),
					'schema' => array( $this, 'get_public_item_schema' ),
				)
			);
		}

		public function get_items_permissions_check( $request ) {
			if ( 'edit' === $request['context'] && ! current_user_can( 'edit_posts' ) ) {
				return new WP_Error(
					'rest_forbidden_context',
					__( 'Sorry, you are not allowed to access the edit context of venues.', 'wpbp' ),
					array( 'status' => 403 )
				);
			}

			return true;
		}

		public function get_items( $request ) {
			$records = get_option( 'wpbp_venues', array() );
			if ( ! is_array( $records ) ) {
				$records = array();
			}

			$items = array();
			foreach ( $records as $record ) {
				$items[] = $this->prepare_item_for_response( $record, $request );
			}

			return rest_ensure_response( $items );
		}

		public function prepare_item_for_response( $item, $request ) {
			$data = array(
				'name'        => isset( $item['name'] ) ? (string) $item['name'] : '',
				'capacity'    => isset( $item['capacity'] ) ? (int) $item['capacity'] : 0,
				'owner_email' => isset( $item['owner_email'] ) ? (string) $item['owner_email'] : '',
			);

			// Let the schema decide which fields survive for the requested context.
			return $this->filter_response_by_context( $data, $request['context'] );
		}

		public function get_item_schema() {
			if ( $this->schema ) {
				return $this->add_additional_fields_schema( $this->schema );
			}

			$this->schema = array(
				'$schema'    => 'http://json-schema.org/draft-04/schema#',
				'title'      => 'wpbp_venue',
				'type'       => 'object',
				'properties' => array(
					'name'        => array(
						'description' => __( 'Venue name.', 'wpbp' ),
						'type'        => 'string',
						'context'     => array( 'view', 'edit' ),
						'readonly'    => true,
					),
					'capacity'    => array(
						'description' => __( 'Venue capacity.', 'wpbp' ),
						'type'        => 'integer',
						'context'     => array( 'view', 'edit' ),
						'readonly'    => true,
					),
					'owner_email' => array(
						'description' => __( 'Venue owner email (private).', 'wpbp' ),
						'type'        => 'string',
						'format'      => 'email',
						'context'     => array( 'edit' ),
						'readonly'    => true,
					),
				),
			);

			return $this->add_additional_fields_schema( $this->schema );
		}

		public function get_collection_params() {
			return array(
				'context' => array(
					'description'       => __( 'Scope under which the request is made; determines fields present in response.', 'wpbp' ),
					'type'              => 'string',
					'enum'              => array( 'view', 'edit' ),
					'default'           => 'view',
					'sanitize_callback' => 'sanitize_key',
					'validate_callback' => 'rest_validate_request_arg',
				),
			);
		}
	}
}

