<?php

function wpbp_rewrite_permalinks_001(): void {
    global $wp, $wp_rewrite;

    if ( ! isset( $wp, $wp_rewrite ) ) {
        return;
    }

    // Register the %wpbp_item% rewrite tag and its matching query variable.
    add_rewrite_tag( '%wpbp_item%', '([^/]+)', 'wpbp_item=' );

    if ( ! in_array( 'wpbp_item', (array) $wp->public_query_vars, true ) ) {
        $wp->add_query_var( 'wpbp_item' );
    }

    // Expose the query variable through the query_vars filter (attached directly, since boot hooks have already fired).
    add_filter(
        'query_vars',
        static function ( array $vars ): array {
            $vars[] = 'wpbp_item';
            return array_values( array_unique( $vars ) );
        }
    );

    // Register the extra permalink structure: items/<item-slug>.
    add_permastruct(
        'wpbp_item',
        'items/%wpbp_item%',
        array(
            'with_front' => false,
            'ep_mask'    => EP_NONE,
        )
    );

    // Ensure the rule is included whenever rewrite rules are generated.
    // No flush is performed here; rules are picked up on the next natural rebuild.
    add_filter(
        'rewrite_rules_array',
        static function ( array $rules ): array {
            $item_rules = array(
                'items/([^/]+)/?$' => 'index.php?wpbp_item=$matches[1]',
            );
            return $item_rules + $rules;
        }
    );
}
