<?php
function wpbp_rewrite_permalinks_006(): void {
    add_filter(
        'query_vars',
        static function (array $vars): array {
            $vars[] = 'wpbp_archive';
            return array_values(array_unique($vars));
        }
    );

    add_filter(
        'rewrite_rules_array',
        static function (array $rules): array {
            $pattern_archive = '^wpbp-archive/?$';
            $query_archive   = 'index.php?wpbp_archive=1';

            $new      = [];
            $inserted = false;

            foreach ($rules as $pattern => $query) {
                if (
                    ! $inserted
                    && is_string($query)
                    && strpos($query, 'index.php?name=$matches[1]') === 0
                ) {
                    $new[$pattern_archive] = $query_archive;
                    $inserted = true;
                }

                if ($pattern !== $pattern_archive) {
                    $new[$pattern] = $query;
                }
            }

            if (! $inserted) {
                $new[$pattern_archive] = $query_archive;
            }

            return $new;
        }
    );
}

