function wpbp_roles_caps_001(): bool {
    $role_name = 'wpbp_manager';

    $role = get_role( $role_name );

    if ( null === $role ) {
        $role = add_role(
            $role_name,
            'WPBP Manager',
            array(
                'read'        => true,
                'wpbp_manage' => true,
            )
        );
    }

    if ( ! $role instanceof WP_Role ) {
        $role = get_role( $role_name );
    }

    if ( ! $role instanceof WP_Role ) {
        return false;
    }

    if ( ! $role->has_cap( 'read' ) ) {
        $role->add_cap( 'read' );
    }

    if ( ! $role->has_cap( 'wpbp_manage' ) ) {
        $role->add_cap( 'wpbp_manage' );
    }

    $verified = get_role( $role_name );

    return $verified instanceof WP_Role
        && $verified->has_cap( 'read' )
        && $verified->has_cap( 'wpbp_manage' );
}
