<?php
/**
 * Returns the primitive capabilities WordPress requires for a user to edit a post.
 *
 * Uses the core meta-capability mapping (map_meta_cap) so that the result
 * reflects the same primitive caps WordPress checks internally for 'edit_post'.
 *
 * @param int $user_id The user ID.
 * @param int $post_id The post ID.
 * @return array List of primitive capability names required.
 */
function wpbp_roles_caps_004( int $user_id, int $post_id ): array {
	$user_id = absint( $user_id );
	$post_id = absint( $post_id );

	if ( $post_id <= 0 ) {
