function wpbp_security_009( string $table, string $fragment ): int {
	global $wpdb;

	// Escape LIKE wildcards (% and _) and backslashes so the fragment matches literally.
	$like = '%' . $wpdb->esc_like( $fragment ) . '%';

	// %i quotes the table name as an SQL identifier; %s escapes the LIKE pattern value.
	$sql = $wpdb->prepare(
		"SELECT COUNT(*) FROM %i WHERE post_title LIKE %s",
		$table,
		$like
	);

	return (int) $wpdb->get_var( $sql );
}
