	$value = sanitize_text_field( $value );
	$value = trim( preg_replace( '/\s{2,}/', ' ', $value ) );

	// Store the cleaned single-line text.
	update_option( 'wpbp_tagline', $value );

	// Escape for each context.
	$attr_value = esc_attr( $value );
	$js_value   = '"' . esc_js( $value ) . '"';

	$snippet  = '<span class="wpbp-tagline" title="' . $attr_value . '"></span>' . "\n";
	$snippet .= '<script>' . "\n";
	$snippet .= 'var wpbpTagline = ' . $js_value . ';' . "\n";
	$snippet .= '</script>';

