$wpbp_brand_palette_filter = static function ( $theme_json ) {
    if ( ! $theme_json instanceof WP_Theme_JSON_Data ) {
        return $theme_json;
    }

    $data = $theme_json->get_data();

    if ( ! isset( $data['settings'] ) || ! is_array( $data['settings'] ) ) {
        $data['settings'] = [];
    }
    if ( ! isset( $data['settings']['color'] ) || ! is_array( $data['settings']['color'] ) ) {
        $data['settings']['color'] = [];
    }
    if ( ! isset( $data['settings']['color']['palette'] ) || ! is_array( $data['settings']['color']['palette'] ) ) {
        $data['settings']['color']['palette'] = [];
    }

    $palette = $data['settings']['color']['palette']['theme'] ?? [];
    if ( ! is_array( $palette ) ) {
        $palette = [];
    }

    $exists = false;
    foreach ( $palette as $entry ) {
        if ( is_array( $entry ) && isset( $entry['slug'] ) && 'wpbp-brand' === $entry['slug'] ) {
            $exists = true;
            break;
        }
    }

    if ( ! $exists ) {
        $palette[] = [
            'name'  => __( 'WPBP Brand', 'default' ),
            'slug'  => 'wpbp-brand',
            'color' => '#123456',
        ];
    }

    $data['settings']['color']['palette']['theme'] = $palette;

    $theme_json->update_with( $data );

    return $theme_json;
};

