<?php
add_filter(
    'get_the_excerpt',
    function ( $excerpt, $post = null ) {
        $post = get_post( $post );

        if ( ! $post ) {
            return $excerpt;
        }

        // Manually written excerpts are returned exactly as written.
        if ( '' !== trim( (string) $post->post_excerpt ) ) {
            return $excerpt;
        }

        $text  = wp_strip_all_tags( (string) $excerpt );
        $words = preg_split( '/\s+/u', trim( $text ), -1, PREG_SPLIT_NO_EMPTY );

        if ( empty( $words ) ) {
            return $excerpt;
        }

        $words = array_slice( $words, 0, 8 );

        return implode( ' ', $words ) . ' [keep reading]';
    },
    999,
    2
);
