<?php

add_filter( 'the_content', 'wpbp_insert_sponsored_promo_block', 8 );

function wpbp_insert_sponsored_promo_block( $content ) {
	if ( ! is_string( $content ) || '' === trim( $content ) || ! has_blocks( $content ) ) {
		return $content;
	}

	$blocks = parse_blocks( $content );

	$real_block_indexes = array();
	foreach ( $blocks as $index => $block ) {
		if ( ! empty( $block['blockName'] ) ) {
			$real_block_indexes[] = $index;
		}
	}

	if ( count( $real_block_indexes ) <= 2 ) {
		return $content;
	}

	$promo_html = '<p class="wpbp-promo">Sponsored by WPBP</p>';

	$promo_block = array(
		'blockName'    => 'core/paragraph',
		'attrs'        => array( 'className' => 'wpbp-promo' ),
		'innerBlocks'  => array(),
		'innerHTML'    => $promo_html,
		'innerContent' => array( $promo_html ),
	);

	array_splice( $blocks, $real_block_indexes[1] + 1, 0, array( $promo_block ) );

	return serialize_blocks( $blocks );
}
