<?php
if ( ! class_exists( 'WPBP_Recent_Items_Widget' ) ) {

	class WPBP_Recent_Items_Widget extends WP_Widget {

		public function __construct() {
			parent::__construct(
				'wpbp-recent-items',
				__( 'Recent Items', 'wpbp' ),
				array(
					'classname'   => 'wpbp-recent-items',
					'description' => __( 'Lists the most recent published entries as links.', 'wpbp' ),
				)
			);
		}

		public function widget( $args, $instance ) {
			$title     = isset( $instance['title'] ) ? $instance['title'] : '';
			$post_type = ! empty( $instance['post_type'] ) ? sanitize_key( $instance['post_type'] ) : 'post';
			$number    = isset( $instance['number'] ) ? absint( $instance['number'] ) : 3;

			if ( ! post_type_exists( $post_type ) ) {
				$post_type = 'post';
			}
			if ( $number < 1 ) {
				$number = 3;
			}

			/** This filter is documented in wp-includes/default-widgets.php */
			$title = apply_filters( 'widget_title', $title, $instance, $this->id_base );

			echo $args['before_widget'];

			if ( ! empty( $title ) ) {
				echo $args['before_title'] . esc_html( $title ) . $args['after_title'];
			}

			$query = new WP_Query(
				array(
					'post_type'           => $post_type,
					'post_status'         => 'publish',
					'posts_per_page'      => $number,
					'orderby'             => 'date',
					'order'               => 'DESC',
					'ignore_sticky_posts' => true,
					'no_found_rows'       => true,
				)
			);

			if ( $query->have_posts() ) {
				echo '<ul>';
				while ( $query->have_posts() ) {
					$query->the_post();
					printf(
						'<li><a href="%1$s">%2$s</a></li>',
						esc_url( get_permalink() ),
						esc_html( get_the_title() )
					);
				}
				echo '</ul>';
				wp_reset_postdata();
			}

			echo $args['after_widget'];
		}

		public function form( $instance ) {
			$title     = isset( $instance['title'] ) ? $instance['title'] : '';
			$post_type = isset( $instance['post_type'] ) ? $instance['post_type'] : 'post';
			$number    = isset( $instance['number'] ) ? absint( $instance['number'] ) : 3;

			$title_id     = $this->get_field_id( 'title' );
			$title_name   = $this->get_field_name( 'title' );
			$type_id      = $this->get_field_id( 'post_type' );
			$type_name    = $this->get_field_name( 'post_type' );
			$number_id    = $this->get_field_id( 'number' );
			$number_name  = $this->get_field_name( 'number' );

			$post_types = get_post_types( array( 'public' => true ), 'objects' );
			?>
			<p>
				<label for="<?php echo esc_attr( $title_id ); ?>"><?php esc_html_e( 'Title:', 'wpbp' ); ?></label>
				<input class="widefat" id="<?php echo esc_attr( $title_id ); ?>" name="<?php echo esc_attr( $title_name ); ?>" type="text" value="<?php echo esc_attr( $title ); ?>" />
			</p>
			<p>
				<label for="<?php echo esc_attr( $type_id ); ?>"><?php esc_html_e( 'Content type:', 'wpbp' ); ?></label>
				<select class="widefat" id="<?php echo esc_attr( $type_id ); ?>" name="<?php echo esc_attr( $type_name ); ?>">
					<?php foreach ( $post_types as $type ) : ?>
						<option value="<?php echo esc_attr( $type->name ); ?>" <?php selected( $post_type, $type->name ); ?>>
							<?php echo esc_html( $type->labels->singular_name ); ?>
						</option>
					<?php endforeach; ?>
				</select>
			</p>
			<p>
				<label for="<?php echo esc_attr( $number_id ); ?>"><?php esc_html_e( 'Number of entries:', 'wpbp' ); ?></label>
				<input class="tiny-text" id="<?php echo esc_attr( $number_id ); ?>" name="<?php echo esc_attr( $number_name ); ?>" type="number" min="1" step="1" value="<?php echo esc_attr( $number ); ?>" />
			</p>
			<?php
		}

		public function update( $new_instance, $old_instance ) {
			$instance = array();

			$instance['title']     = sanitize_text_field( $new_instance['title'] ?? '' );
			$instance['post_type'] = sanitize_key( $new_instance['post_type'] ?? 'post' );
			$instance['number']    = max( 1, absint( $new_instance['number'] ?? 3 ) );

			if ( ! post_type_exists( $instance['post_type'] ) ) {
				$instance['post_type'] = 'post';
			}

			return $instance;
		}
	}
}

